","import React from "react";
import ReactDOM from "react-dom/client";
import App from "./app";

ReactDOM.createRoot(document.getElementById("root")!).render(<App />);
","import React, { useEffect, useState } from "react";
import DashboardLayout from "../components/DashboardLayout";
import KpiCard from "../components/KpiCard";
import { getCount } from "../services/api";
import { NowRecordListConnected } from "@servicenow/react-components/NowRecordListConnected";
import "./app.css";

const App: React.FC = () => {
 const [openRequests, setOpenRequests] = useState(0);
 const [pendingDocs, setPendingDocs] = useState(0);
 const [trainingCompleted, setTrainingCompleted] = useState(0);
 const [overdueItems, setOverdueItems] = useState(0);

 useEffect(() => {
 const load = async () => {
 const [reqs, docs, training, overdue] = await Promise.all([
 getCount("sc_request", "stageINrequested,in_process"),
 getCount("x_2182380_pwcnow_employee_document", "u_status=pending"),
 getCount("x_2182380_pwcnow_employee_training", "u_status=completed"),
 getCount(
 "x_2182380_pwcnow_employee_training",
 "u_status!=completed^u_due_date<javascript:gs.nowDateTime()"
 ),
 ]);
 setOpenRequests(reqs);
 setPendingDocs(docs);
 setTrainingCompleted(training);
 setOverdueItems(overdue);
 };
 load();
 }, []);

 return (
 <DashboardLayout
 title="Director Dashboard"
 subtitle="Organization-wide overview"
 >
 <div className="kpi-grid">
 <KpiCard label="Total Open Requests" value={openRequests} />
 <KpiCard label="Pending Documents" value={pendingDocs} />
 <KpiCard label="Training Completed" value={trainingCompleted} />
 <KpiCard
 label="Overdue Items"
 value={overdueItems}
 color="rgb(200, 50, 50)"
 />
 </div>
 <section className="record-list-section">
 <h2 className="section-title">Recent Requests</h2>
 <NowRecordListConnected
 table="sc_request"
 listTitle="Recent Requests"
 columns="number,requested_for,stage,approval,sys_created_on"
 hideHeader={true}
 limit={10}
 />
 </section>
 </DashboardLayout>
 );
};

export default App;
